import sys
from collections import defaultdict

def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n = data[0]
    a = data[1:]

    factors = []
    primes = set()
    for x in a:
        fs = {}
        d = 2
        while d * d <= x:
            if x % d == 0:
                e = 0
                while x % d == 0:
                    x //= d
                    e += 1
                fs[d] = e
                primes.add(d)
            d += 1
        if x > 1:
            fs[x] = 1
            primes.add(x)
        factors.append(fs)

    answer = 1
    for p in primes:
        steps = [f.get(p, 0) for f in factors]
        total = sum(steps)
        max_step = max(steps, default=0)
        # Covers both cumulative height contributions and the adjustment
        # when a new prefix minimum is reached.
        powers = [1] * (n * max_step + total + 2)
        for i in range(1, len(powers)):
            powers[i] = powers[i - 1] * p % MOD

        # z is the current height above the minimum; the value is the
        # weighted sum for all normalized prefixes ending at height z.
        dp = {0: 1}
        k = 1  # number of vertices in the current prefix
        for e in steps:
            nxt = defaultdict(int)
            if e == 0:
                for z, value in dp.items():
                    nxt[z] = (nxt[z] + value * powers[z]) % MOD
            else:
                for z, value in dp.items():
                    for delta in (-e, e):
                        y = z + delta
                        if y >= 0:
                            new_z = y
                            multiplier = powers[y]
                        else:
                            new_z = 0
                            multiplier = powers[(-y) * k]
                        nxt[new_z] = (nxt[new_z] + value * multiplier) % MOD
            dp = nxt
            k += 1
        answer = answer * (sum(dp.values()) % MOD) % MOD

    print(answer)

if __name__ == '__main__':
    solve()

