import sys

def main():
    data=list(map(int,sys.stdin.buffer.read().split()))
    if not data: return
    n,q=data[:2]; p=2
    parent=list(range(n)); sz=[1]*n
    left=list(range(n)); right=list(range(n)); color=list(range(1,n+1))
    cnt=[0]*(n+1)
    for i in range(1,n+1): cnt[i]=1
    def find(x):
        r=x
        while parent[r]!=r: r=parent[r]
        while parent[x]!=x:
            y=parent[x]; parent[x]=r; x=y
        return r
    def union(a,b):
        if sz[a]<sz[b]: a,b=b,a
        parent[b]=a; sz[a]+=sz[b]
        left[a]=min(left[a],left[b]); right[a]=max(right[a],right[b])
        return a
    out=[]
    for _ in range(q):
        t=data[p]; p+=1
        if t==1:
            x,c=data[p]-1,data[p+1]; p+=2
            r=find(x); old=color[r]
            if old!=c:
                cnt[old]-=sz[r]; cnt[c]+=sz[r]; color[r]=c
            if left[r]>0:
                a=find(left[r]-1)
                if color[a]==c:
                    r=union(r,a)
            if right[r]<n-1:
                a=find(right[r]+1)
                if color[a]==c:
                    r=union(r,a)
        else:
