from typing import List
import heapq
class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        at=[[] for _ in range(n+1)]
        for i,(x,y) in enumerate(conflictingPairs):
            a,b=sorted((x,y)); at[b].append((a,i))
        heap=[]
        counts=[0]*(n+1)
        sole=[-1]*(n+1)
        gains=[0]*len(conflictingPairs)
        base=0
        for r in range(1,n+1):
            for a,i in at[r]:
                heapq.heappush(heap,(-a,i))
                counts[a]+=1
                sole[a]=i if counts[a]==1 else -1
            if heap:
                top=-heap[0][0]
                second=-heap[1][0] if len(heap)>1 else 0
            else:
                top=second=0
            base += r-top
            if top and counts[top]==1:
                gains[sole[top]] += top-second
        return base+max(gains)

