        for i in range(n):
            dik=d[i][k]
            if dik==inf: continue
            di=d[i]
            for j in range(n):
                v=dik+dk[j]
                if v<di[j]: di[j]=v
    ans=[]
    for qu in reversed(queries):
        if qu[0]==2:
            v=d[qu[1]][qu[2]]
