class SegTree:
    def __init__(self, n):
        self.mx = [-10**9] * (4 * n)
        self.lazy = [0] * (4 * n)

    def add(self, node, left, right, ql, qr, value):
        if ql <= left and right <= qr:
            self.mx[node] += value
            self.lazy[node] += value
            return
        mid = (left + right) // 2
        if ql <= mid:
            self.add(node * 2, left, mid, ql, qr, value)
        if qr > mid:
            self.add(node * 2 + 1, mid + 1, right, ql, qr, value)
        self.mx[node] = self.lazy[node] + max(self.mx[node * 2], self.mx[node * 2 + 1])

    def set_value(self, node, left, right, index, value):
        if left == right:
            self.mx[node] = value
            self.lazy[node] = 0
            return
        mid = (left + right) // 2
        if index <= mid:
            self.set_value(node * 2, left, mid, index, value)
        else:
            self.set_value(node * 2 + 1, mid + 1, right, index, value)
        self.mx[node] = self.lazy[node] + max(self.mx[node * 2], self.mx[node * 2 + 1])


