class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 10**9 + 7
        length = len(s)
        # ways[w] is the number of values below n with popcount w.
        ways = [0] * (length + 1)
        prefix_ones = 0
        for i, bit in enumerate(s):
            if bit == '1':
                remaining = length - i - 1
                for suffix_ones in range(remaining + 1):
                    ways[prefix_ones + suffix_ones] += __import__('math').comb(remaining, suffix_ones)
                prefix_ones += 1

        def reductions_to_one(x):
            count = 0
            while x != 1:
                x = x.bit_count()
                count += 1
            return count

        answer = 0
        for weight in range(1, length + 1):
            # The first popcount operation produces 'weight'; weight=1 is already 1.
            if weight == 1 or reductions_to_one(weight) + 1 <= k:
                answer += ways[weight]
        return answer % MOD

