class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 10**9 + 7
        nbits = len(s)
        # ways[w] counts numbers strictly less than n having exactly w set bits.
        ways = [0] * (nbits + 1)
        prefix = 0
        for i, ch in enumerate(s):
            if ch == '1':
                rem = nbits - i - 1
                for r in range(rem + 1):
                    ways[prefix + r] += __import__('math').comb(rem, r)
                prefix += 1
        # Reduce each possible popcount repeatedly until reaching 1.
        def steps(x):
            count = 0
            while x != 1:
                x = x.bit_count()
                count += 1
            return count
        ans = 0
        for w in range(1, nbits + 1):
            if w == 1 or steps(w) + 1 <= k:
                ans += ways[w]
        return ans % MOD

