def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, x = data[0], data[1]
    U = data[2::2]
    D = data[3::2]

    def feasible(h):
        lo = max(0, h - D[0])
        hi = min(U[0], h)
        if lo > hi:
            return False
        for i in range(1, n):
            lo = max(0, h - D[i], lo - x)
            hi = min(U[i], h, hi + x)
            if lo > hi:
                return False
        return True

    low = 0
    high = min(u + d for u, d in zip(U, D))
    while low < high:
        mid = (low + high + 1) // 2
        if feasible(mid):
            low = mid
        else:
            high = mid - 1

    print(sum(U) + sum(D) - n * low)

if __name__ == '__main__':
    main()

