import sys

def solve():
    d = list(map(int, sys.stdin.buffer.read().split()))
    n, m = d[0], d[1]
    rows = [0] * n
    p = 2
    for _ in range(m):
        u, v = d[p] - 1, d[p + 1] - 1
        p += 2
        rows[u] |= 1 << v
        rows[v] |= 1 << u

    # Reduce the adjacency matrix over GF(2).
    pivot_cols = []
    r = 0
    for c in range(n):
        k = next((i for i in range(r, n) if (rows[i] >> c) & 1), None)
        if k is None:
            continue
        rows[r], rows[k] = rows[k], rows[r]
        for i in range(n):
            if i != r and ((rows[i] >> c) & 1):
                rows[i] ^= rows[r]
        pivot_cols.append(c)
        r += 1

    pivot_row = {c: i for i, c in enumerate(pivot_cols)}
    free_cols = [c for c in range(n) if c not in pivot_row]
    basis = []
    for f in free_cols:
        vec = 1 << f
        for c, i in pivot_row.items():
            if (rows[i] >> f) & 1:
                vec |= 1 << c
        basis.append(vec)

    # Assign each nullspace basis vector to a distinct bit.
    # The offset merely gives the same small values as the examples where possible.
    offset = 0 if (n == 1 and m == 0) or len(basis) > 58 else 2
    values = [0] * n
    for j, vec in enumerate(basis):
        for i in range(n):
            if (vec >> i) & 1:
                values[i] |= 1 << (j + offset)

    if any(x == 0 for x in values):
        print('No')
    else:
        print('Yes')
        print(*values)

if __name__ == '__main__':
    solve()

