    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n, m = len(grid), len(grid[0])
        dirs = [(1,1),(1,-1),(-1,-1),(-1,1)]
        straight = [[[0]*m for _ in range(n)] for _ in range(4)]
        turn = [[[0]*m for _ in range(n)] for _ in range(4)]
        # clockwise rotation in row/column coordinates
        cw = [1,2,3,0]
        for d, (dr,dc) in enumerate(dirs):
            rows = range(n-1,-1,-1) if dr == 1 else range(n)
            cols = range(m-1,-1,-1) if dc == 1 else range(m)
            for r in rows:
                for c in cols:
                    val = grid[r][c]
                    if val == 1:
                        continue
                    nr,nc = r+dr,c+dc
                    if 0 <= nr < n and 0 <= nc < m and grid[nr][nc] == 2-val:
                        straight[d][r][c] = 1 + straight[d][nr][nc]
                        turn[d][r][c] = 1 + max(turn[d][nr][nc], straight[cw[d]][nr][nc])
                    else:
                        straight[d][r][c] = turn[d][r][c] = 1
        ans = 0
        for r in range(n):
            for c in range(m):
                if grid[r][c] != 1:
                    continue
                ans = max(ans, 1)
                for d,(dr,dc) in enumerate(dirs):
                    nr,nc=r+dr,c+dc
                    if 0 <= nr < n and 0 <= nc < m and grid[nr][nc] == 2:
                        ans=max(ans,1+turn[d][nr][nc])
        return ans

