class Solution:
    def distanceSum(self, m: int, n: int, k: int) -> int:
        MOD = 10**9 + 7
        total = m * n
        dist = n * n * (m * (m - 1) * (m + 1) // 6) + m * m * (n * (n - 1) * (n + 1) // 6)
        fact = [1] * (total + 1)
        for i in range(1, total + 1):
            fact[i] = fact[i - 1] * i % MOD
        ways = fact[total - 2] * pow(fact[k - 2], MOD - 2, MOD) % MOD * pow(fact[total - k], MOD - 2, MOD) % MOD
        return dist % MOD * ways % MOD

