class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        m = (n + 1) // 2
        powers = [1] * n
        for i in range(1, n):
            powers[i] = powers[i - 1] * 10 % k

        coeff = []
        for i in range(m):
            j = n - 1 - i
            coeff.append((powers[i] + (powers[j] if j != i else 0)) % k)

        # Bit r in reachable[i] means the remaining positions can contribute
        # a value congruent to r modulo k.
        reachable = [0] * (m + 1)
        reachable[m] = 1  # Only residue 0 is reachable with no positions left.
        for i in range(m - 1, -1, -1):
            c = coeff[i]
            following = reachable[i + 1]
            mask = 0
            for r in range(k):
                if (following >> r) & 1:
                    for d in range(10):
                        mask |= 1 << ((r + d * c) % k)
            reachable[i] = mask

        digits = []
        residue = 0
        for i, c in enumerate(coeff):
            # The outermost digit cannot be zero.
            lowest = 1 if i == 0 else 0
            for d in range(9, lowest - 1, -1):
                need = (-residue - d * c) % k
                if (reachable[i + 1] >> need) & 1:
                    digits.append(str(d))
                    residue = (residue + d * c) % k
                    break

        left = ''.join(digits)
        return left + (left[:-1][::-1] if n % 2 else left[::-1])

