from typing import List

class Solution:
    def countNonDecreasingSubarrays(self, nums: List[int], k: int) -> int:
        n = len(nums)

        # next greater element to the right; these indices delimit runs of
        # equal prefix maxima when the left endpoint is fixed.
        nxt = [n] * n
        stack = []
        for i in range(n - 1, -1, -1):
            while stack and nums[stack[-1]] <= nums[i]:
                stack.pop()
            nxt[i] = stack[-1] if stack else n
            stack.append(i)

        # Binary lifting over the successive prefix-maximum runs. sums[p][i]
        # is the sum of the maximum values over the runs crossed by jump[p][i].
        jump = [nxt]
        sums = [[nums[i] * (nxt[i] - i) for i in range(n)]]
        while (1 << len(jump)) <= n:
            prev_jump = jump[-1]
            prev_sum = sums[-1]
            cur_jump = [n] * n
            cur_sum = [0] * n
            for i in range(n):
                mid = prev_jump[i]
                if mid < n:
                    cur_jump[i] = prev_jump[mid]
                    cur_sum[i] = prev_sum[i] + prev_sum[mid]
                else:
                    cur_sum[i] = prev_sum[i]
            jump.append(cur_jump)
            sums.append(cur_sum)

        prefix = [0]
        for x in nums:
            prefix.append(prefix[-1] + x)

        def operation_cost(left: int, right: int) -> int:
            # Sum of prefix maxima on [left, right], via complete runs and
            # the possibly truncated final run.
            pos = left
            maximum_sum = 0
            for p in range(len(jump) - 1, -1, -1):
                if pos == n:
                    break
                end = jump[p][pos]
                if end <= right + 1:
                    maximum_sum += sums[p][pos]
                    pos = end
            if pos <= right:
                maximum_sum += nums[pos] * (right - pos + 1)
            return maximum_sum - (prefix[right + 1] - prefix[left])

        answer = 0
        for left in range(n):
            # Feasibility is monotone as the right endpoint moves right.
            low, high = left, n
            while low < high:
                mid = (low + high + 1) // 2  # exclusive endpoint
                if mid == left or operation_cost(left, mid - 1) <= k:
                    low = mid
                else:
                    high = mid - 1
            answer += low - left
        return answer

