from functools import cmp_to_key
import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n, k = data[0], data[1]
    funcs = list(zip(data[2::2], data[3::2]))

    # Outer-to-inner optimal order is increasing B/(A-1), with A=1 last.
    def compare(x, y):
        a, b = x
        c, d = y
        if a == 1:
            return 0 if c == 1 else 1
        if c == 1:
            return -1
        lhs = b * (c - 1)
        rhs = d * (a - 1)
        return (lhs > rhs) - (lhs < rhs)

    funcs.sort(key=cmp_to_key(compare), reverse=True)  # process inner to outer

    # dp[t]: best result using t processed functions; each new function is outer.
    dp = [None] * (k + 1)
    dp[0] = 1
    for a, b in funcs:
        for t in range(k, 0, -1):
            if dp[t - 1] is not None:
                value = a * dp[t - 1] + b
                if dp[t] is None or value > dp[t]:
                    dp[t] = value
    print(dp[k])

if __name__ == '__main__':
    main()

