from typing import List

class Solution:
    def maximizeSumOfWeights(self, edges: List[List[int]], k: int) -> int:
        n = len(edges) + 1
        adj = [[] for _ in range(n)]
        for u, v, w in edges:
            adj[u].append((v, w))
            adj[v].append((u, w))

        parent = [-1] * n
        parent[0] = 0
        order = [0]
        for u in order:
            for v, _ in adj[u]:
                if v != parent[u]:
                    parent[v] = u
                    order.append(v)

        dp0 = [0] * n  # Parent edge absent
        dp1 = [0] * n  # Parent edge present
        for u in reversed(order):
            base = 0
            gains = []
            for v, w in adj[u]:
                if parent[v] == u:
                    base += dp0[v]
                    gains.append(w + dp1[v] - dp0[v])
            gains.sort(reverse=True)
            dp0[u] = base + sum(max(0, x) for x in gains[:k])
            dp1[u] = base + sum(max(0, x) for x in gains[:max(0, k - 1)])

        return dp0[0]

