from bisect import bisect_left

class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        n = len(s)
        a, b, c = p.split('*')

        def occurrences(word):
            if not word:
                return list(range(n + 1))
            # KMP prefix function
            m = len(word)
            pi = [0] * m
            j = 0
            for i in range(1, m):
                while j and word[i] != word[j]:
                    j = pi[j - 1]
                if word[i] == word[j]:
                    j += 1
                pi[i] = j
            ans = []
            j = 0
            for i, ch in enumerate(s):
                while j and ch != word[j]:
                    j = pi[j - 1]
                if ch == word[j]:
                    j += 1
                if j == m:
                    ans.append(i - m + 1)
                    j = pi[j - 1]
            return ans

        apos, bpos, cpos = occurrences(a), occurrences(b), occurrences(c)
        best = n + 1
        for i in apos:
            x = bisect_left(bpos, i + len(a))
            if x == len(bpos):
                continue
            bj = bpos[x]
            y = bisect_left(cpos, bj + len(b))
            if y == len(cpos):
                continue
            end = cpos[y] + len(c)
            best = min(best, end - i)
        return -1 if best == n + 1 else best

