class Solution:
    def minOperations(self, n: int, m: int) -> int:
        digits = len(str(n))
        if len(str(m)) != digits:
            return -1

        lo = 10 ** (digits - 1)
        hi = 10 ** digits - 1

        # Sieve primes in the complete range of possible same-length values.
        is_prime = bytearray(b'\x01') * (hi + 1)
        is_prime[0] = is_prime[1] = 0
        for p in range(2, int(hi ** 0.5) + 1):
            if is_prime[p]:
                start = p * p
                count = (hi - start) // p + 1
                is_prime[start:hi + 1:p] = b'\x00' * count

