from typing import List

class Solution:
    def beautifulSplits(self, nums: List[int]) -> int:
        n = len(nums)
        if n < 3:
            return 0

        # Z[i] is the LCP of nums and nums[i:].
        z = [0] * n
        left = right = 0
        for i in range(1, n):
            if i < right:
                z[i] = min(right - i, z[i - left])
            while i + z[i] < n and nums[z[i]] == nums[i + z[i]]:
                z[i] += 1
            if i + z[i] > right:
                left, right = i, i + z[i]

        # Condition nums1 is a prefix of nums2. For a fixed first
        # segment length i, the second segment can have any length >= i.
        answer = sum(
            n - 2 * i
            for i in range(1, (n - 1) // 2 + 1)
            if z[i] >= i
        )

        # For each distance d = j-i, test whether the adjacent segments
        # nums[i:j] and nums[j:j+d] are equal. The LCP along each diagonal
        # is computed in reverse with a single running value.
        for d in range(1, n):
            common = 0
            for i in range(n - d - 1, 0, -1):
                if nums[i] == nums[i + d]:
                    common += 1
                else:
                    common = 0

                if common >= d:
                    answer += 1
                    # Avoid counting splits that satisfy both conditions.
                    if d >= i and z[i] >= i:
                        answer -= 1

        return answer

