from typing import List

class Solution:
    def maxRemovals(self, source: str, pattern: str, targetIndices: List[int]) -> int:
        n = len(source)
        m = len(pattern)
        removable = [False] * n
        for i in targetIndices:
            removable[i] = True

        neg = -10**9
        dp = [neg] * (m + 1)
        dp[0] = 0

        for i, ch in enumerate(source):
            # Keep this character without using it in the subsequence.
            ndp = dp[:]

            # Or remove it, if its original index is allowed.
            if removable[i]:
                for j in range(m + 1):
                    if dp[j] != neg:
                        ndp[j] = max(ndp[j], dp[j] + 1)

            # Or keep it as the next character of the pattern.
            for j in range(m):
                if ch == pattern[j] and dp[j] != neg:
                    ndp[j + 1] = max(ndp[j + 1], dp[j])

            dp = ndp

        return dp[m]

