class Solution:
    def minMaxWeight(self, n: int, edges: List[List[int]], threshold: int) -> int:
        # Reverse adjacency: from v, visit every u with an original edge u -> v.
        incoming = [[] for _ in range(n)]
        max_weight = 0
        for a, b, w in edges:
            incoming[b].append((a, w))
            if w > max_weight:
                max_weight = w

        def reachable(limit: int) -> bool:
            seen = bytearray(n)
            seen[0] = 1
            stack = [0]
            count = 1
            while stack:
                v = stack.pop()
                for u, w in incoming[v]:
                    if w <= limit and not seen[u]:
                        seen[u] = 1
                        count += 1
                        stack.append(u)
            return count == n

        if not reachable(max_weight):
            return -1

        lo, hi = 1, max_weight
        while lo < hi:
            mid = (lo + hi) // 2
            if reachable(mid):
                hi = mid
            else:
                lo = mid + 1
        return lo

