class Solution:
    def minCost(self, n: int, cost: List[List[int]]) -> int:
        # A state is the pair of colors at symmetric positions.
        states = [(a, b) for a in range(3) for b in range(3) if a != b]
        inf = 10**30
        dp = [cost[0][a] + cost[n - 1][b] for a, b in states]

        for i in range(1, n // 2):
            ndp = [inf] * len(states)
            for p, (a, b) in enumerate(states):
                for q, (c, d) in enumerate(states):
                    # Moving inward, each side's new color must differ
                    # from its previous (adjacent) house.
                    if c != a and d != b:
                        value = dp[p] + cost[i][c] + cost[n - 1 - i][d]
                        if value < ndp[q]:
                            ndp[q] = value
            dp = ndp

