class Solution:
    def maxActiveSectionsAfterTrade(self, s: str) -> int:
        ones = s.count('1')
        best = 0
        n = len(s)
        i = 0
        # Runs represented as (character, length)
        runs = []
        while i < n:
            j = i + 1
            while j < n and s[j] == s[i]:
                j += 1
            runs.append((s[i], j - i))
            i = j
        for k in range(1, len(runs) - 1):
            if runs[k][0] == '1' and runs[k-1][0] == '0' and runs[k+1][0] == '0':
                best = max(best, runs[k-1][1] + runs[k+1][1])
        return ones + best

