        vowels = set('aeiou')
        answer = 0
        n = len(word)
        for left in range(n):
            seen = set()
            consonants = 0
            for right in range(left, n):
                ch = word[right]
                if ch in vowels:
                    seen.add(ch)
                else:
                    consonants += 1
                    if consonants > k:
                        break
                if consonants == k and len(seen) == 5:
                    answer += 1
        return answer

# Public examples
s = Solution()
assert s.countOfSubstrings('aeioqq', 1) == 0
assert s.countOfSubstrings('aeiou', 0) == 1
assert s.countOfSubstrings('ieaouqqieaouqq', 1) == 3
